function d_tfidf_rank(P,R){var docs=P.docs||[],q=(P.query||'').toLowerCase().split(/\s+/);var N=docs.length;var df={};docs.forEach(function(d){var seen={};d.text.toLowerCase().split(/\s+/).forEach(function(w){if(!seen[w]){seen[w]=1;df[w]=(df[w]||0)+1;}});});var sc=docs.map(function(d){var terms=d.text.toLowerCase().split(/\s+/);var s=0;q.forEach(function(w){var tf=terms.filter(function(t){return t===w;}).length/Math.max(1,terms.length);var idf=Math.log(1+N/Math.max(1,df[w]||0));s+=tf*idf;});return{id:d.id,score:+s.toFixed(4)};}).sort(function(a,b){return b.score-a.score;});return{query:P.query,ranking:sc.slice(0,3)};}

